218	        </MotionChakraDiv>
219	      </chakra.div>
220	    </ModalFocusScope>
221	  );
222	};
223	
224	/**
225	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
226	 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
227	 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
