229	 *
230	 * Pass `title` to render an inline header row (title text left, close button right) sized per the
231	 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
232	 * that supply their own header (e.g. ZimmPdpDrawer's tab row) — the close button floats on its own
233	 * by default. Add `boxedHeader` alongside `labelledBy` when the drawer has no header content of its
234	 * own (e.g. ZimmCountryLanguageMismatch, whose heading lives in its body) but still wants the close
235	 * button sitting in that same in-flow header row rather than floating over the content.
236	 *
237	 * @param props see ZimmDrawerProps
238	 */
239	export const ZimmDrawer = (props: ZimmDrawerProps) => {
240	  const { isOpen, onClose, size, children, titleStyle = 'large', finalFocusRef, initialFocusRef } = props;
241	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
242	  const titleId = useId();
243	
244	  // Figma-fidelity audit fix, 2026-09-19: without an explicit `initialFocusRef`, Chakra's Drawer
245	  // defaults to auto-focusing the first focusable descendant — for every real consumer that
246	  // doesn't set one (ZimmCartDrawer, ZimmPdpDrawer), that's the close button. Reproduced live:
247	  // when nothing has focus and no prior user interaction exists yet (confirmed exactly matching
248	  // how a Storybook story that mounts already-open behaves, and plausible for a real first
249	  // render too), the browser's native `:focus-visible` heuristic has no basis to rule out a
250	  // keyboard interaction and defaults to showing the ring — on the close button, on every open,
251	  // regardless of whether the shopper used a mouse, touch, or keyboard to get there. `panelRef`
252	  // gives Chakra a neutral target instead: the dialog's own panel, `tabIndex={-1}` so it's
253	  // programmatically focusable without joining the normal Tab order. This still satisfies the
254	  // real requirement (focus moves into the dialog immediately, so keyboard/AT users land
255	  // somewhere sane and Tab/Escape work correctly from there) without ever auto-focusing an
256	  // interactive element nobody actually interacted with. A consumer that explicitly passes its
257	  // own `initialFocusRef` (ZimmWishlistAuthDrawer, straight to its email field) is untouched —
258	  // this only changes the *default* Chakra would otherwise have picked.
259	  const panelRef = useRef<HTMLDivElement>(null);
260	
261	  const title = 'title' in props ? props.title : undefined;
262	  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
263	  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;
264	  const boxedHeader = !title && 'labelledBy' in props ? props.boxedHeader : undefined;
265	
266	  // SFCC-926 — tester reported body scroll still active while any drawer is open, allowing
267	  // the page behind the overlay to scroll alongside the drawer. ZimmDrawer bypasses Chakra's
268	  // own <DrawerContent>, so blockScrollOnMount may not fire. Locking body overflow explicitly
269	  // ensures only the drawer's internal scroll area is accessible while it is open.
270	  // Uses the module-level counter so multiple open instances don't race to restore overflow.
271	  useEffect(() => {
272	    if (!isOpen) return;
273	    if (scrollLockCount === 0) {
274	      scrollLockPrev = document.body.style.overflow;
275	      document.body.style.overflow = 'hidden';
276	    }
277	    scrollLockCount++;
278	    return () => {
279	      scrollLockCount--;
280	      if (scrollLockCount === 0) {
281	        document.body.style.overflow = scrollLockPrev;
282	        scrollLockPrev = '';
283	      }
284	    };
285	  }, [isOpen]);
286	
287	  // Chakra's FocusLock remains active during the exit animation, so any focus call made
288	  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
289	  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
290	  // reliable moment to restore focus. Covers both close-button click and Escape for all
291	  // consumers that pass finalFocusRef.
292	  const handleCloseComplete = () => {
293	    if (finalFocusRef) finalFocusRef.current?.focus();
294	  };
295	
296	  return (
297	    <Drawer
298	      isOpen={isOpen}
299	      onClose={onClose}
300	      placement="right"
301	      onCloseComplete={handleCloseComplete}
302	      initialFocusRef={initialFocusRef ?? panelRef}
303	    >
304	      <DrawerOverlay sx={styles.overlay} />
305	      {/* aria-labelledby (not aria-label) for the title case: Chakra's own <DrawerContent>
306	          would clobber it with its own headingId (undefined without a DrawerHeader), but
307	          ZimmDrawerContent bypasses <DrawerContent> entirely and sets dialogProps itself
308	          (see its own comment above) — the clobbering bug this would otherwise work around
309	          doesn't apply here, so referencing the visible title node is safe and preferred. */}
310	      <ZimmDrawerContent
311	        onClose={onClose}
312	        title={title}
313	        titleId={title ? titleId : undefined}
314	        titleStyle={titleStyle}
315	        labelledBy={labelledBy}
316	        ariaLabel={ariaLabel}
317	        boxedHeader={boxedHeader}
318	        contentStyles={styles.content}
319	        headerStyles={styles.header}
320	        headerTitleStyles={styles.headerTitle}
321	        closeButtonStyles={styles.closeButton}
322	        panelRef={panelRef}
323	        headerCloseButtonStyles={styles.headerCloseButton}
324	      >
325	        {children}
326	      </ZimmDrawerContent>
327	    </Drawer>
328	  );
329	};
