// `@param {('push'|'replace')} action`) is used instead of `any`, matching typescript.md's
// preference for `unknown`/a narrow type over an unexplained `any`.
type NavigateFn = (path: string, action?: 'push' | 'replace', ...args: unknown[]) => void;

