1	/*
2	 * Tests for the Zimmermann-added contract in product-view/index.tsx.
3	 *
4	 * Covers:
5	 *   - ZimmSizeSelector render (present / absent based on variationAttributes)
6	 *   - showActionButtons=false suppressing the Add to Bag button when no size attr is present
7	 *   - isSelectedSizeOOS → ariaDisabled on the inline ZimmButton
8	 *   - handleAddToBag → setHasAddToBagError → showError on ZimmSizeSelector
9	 *
10	 * Architecture note on showActionButtons vs the inline ZimmButton:
11	 *   showActionButtons=false suppresses the sticky-mobile CTA bar and the desktop
12	 *   renderActionButtons() box. It does NOT suppress the ZimmSizeSelector or the ZimmButton
13	 *   rendered inline inside the variationAttributes.map() size branch. That inline pair is
14	 *   the Add-to-Bag the PDP uses (showActionButtons=false is the PDP flag). Tests that
15	 *   exercise the inline button therefore pass showActionButtons={false} to prevent the
16	 *   sticky bar from adding a second data-testid="zimm-add-to-bag" match.
17	 */
18	
19	import React from 'react';
20	import { describe, test, expect, vi, beforeEach } from 'vitest';
21	import { render, screen, waitFor } from '@testing-library/react';
22	import userEvent from '@testing-library/user-event';
23	import ProductView from './index';
24	import { useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
25	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
26	
27	// ─── Module-level mocks ───────────────────────────────────────────────────────
28	
29	// react-router-dom: ProductView calls useLocation() for URL colour params and
30	// pathname-based effect cleanup.
31	vi.mock('react-router-dom', () => ({
32	  useLocation: vi.fn(() => ({ search: '', pathname: '/product/test-product' })),
33	}));
34	
35	// react-intl: stub useIntl so formatMessage returns defaultMessage; stub
36	// FormattedMessage to render its defaultMessage prop directly.
37	vi.mock('react-intl', async (importOriginal) => {
38	  const actual = await importOriginal<typeof import('react-intl')>();
39	  return {
40	    ...actual,
41	    useIntl: vi.fn(() => ({
42	      formatMessage: (msg: { defaultMessage?: string }) => msg.defaultMessage ?? '',
43	    })),
44	    FormattedMessage: ({ defaultMessage }: { defaultMessage: string }) => <>{defaultMessage}</>,
45	  };
46	});
47	
48	// @salesforce/retail-react-app/app/components/shared/ui re-exports Chakra UI.
49	// Stubbed with plain HTML so no real Chakra theme/provider is needed.
50	vi.mock('@salesforce/retail-react-app/app/components/shared/ui', () => ({
51	  Flex: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
52	  Box: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
53	  VStack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
54	  HStack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
55	  Heading: ({ children }: React.PropsWithChildren) => <h2>{children}</h2>,
56	  Button: ({
57	    children,
58	    onClick,
59	    disabled,
60	    isLoading,
61	  }: React.PropsWithChildren<{
62	    onClick?: React.MouseEventHandler;
63	    disabled?: boolean;
64	    isLoading?: boolean;
65	  }>) => (
66	    <button onClick={onClick} disabled={disabled ?? isLoading}>
67	      {children}
68	    </button>
69	  ),
70	  Skeleton: ({ children }: React.PropsWithChildren) => <>{children}</>,
71	  Text: ({ children }: React.PropsWithChildren) => <span>{children}</span>,
72	  Fade: ({ children }: React.PropsWithChildren) => <>{children}</>,
73	  Stack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
74	  Radio: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
75	  RadioGroup: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
76	  // useTheme is called for `theme.shadows.top` in the sticky mobile bar.
77	  useTheme: vi.fn(() => ({ shadows: { top: 'none' } })),
78	}));
79	
80	// useCurrency and useDerivedProduct live in this barrel.
81	vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
82	  useCurrency: vi.fn(() => ({ currency: 'AUD' })),
83	  useDerivedProduct: vi.fn(),
84	}));
85	
86	// ProductView now calls useSafeHref() (regional link prefixing fix for related-swatch hrefs) —
87	// mocked at its own module boundary (identity function) rather than reaching through to the real
88	// useMultiSite/MultiSiteContext chain, which has a known JSX-in-.js Vitest parse failure. See
89	// zimmLink/index.test.tsx's identical comment; this suite doesn't assert on prefixing itself
90	// (that's useSafeHref.test.ts's job), just needs ProductView to render without it throwing.
91	vi.mock('app/hooks/useSafeHref', () => ({
92	  useSafeHref: () => (href: string) => href,
93	}));
