describe('App (SFCC-315 — bag icon opens the cart drawer instead of navigating)', () => {
  beforeEach(() => {
    historyPushSpy.mockClear();
    cartDrawerOnOpenSpy.mockClear();
    cartDrawerOnCloseSpy.mockClear();
    capturedOnMyCartClick = undefined;
    drawerMenuSpy.mockClear();
  });

  test('calls the cart drawer\'s onOpen with the real clicked element, and never navigates', () => {
    render(
      <App>
        <div>page content</div>
      </App>,
    );

    // Stands in for the real IconButton RightBar renders — the same element React would pass as
    // e.currentTarget on a real click, since Header/RightBar thread onMyCartClick through
    // unwrapped (see _app/index.tsx's own onCartClick comment).
    const fakeBagIcon = document.createElement('button');
    act(() =>
      capturedOnMyCartClick?.({ currentTarget: fakeBagIcon } as unknown as React.SyntheticEvent<HTMLElement>),
    );

    expect(cartDrawerOnOpenSpy).toHaveBeenCalledWith(fakeBagIcon);
    expect(historyPushSpy).not.toHaveBeenCalled();
  });

  test('falls back to null when no event is supplied, rather than throwing', () => {
    render(
      <App>
        <div>page content</div>
      </App>,
    );

    act(() => capturedOnMyCartClick?.());

    expect(cartDrawerOnOpenSpy).toHaveBeenCalledWith(null);
  });

  test('still closes the mobile nav drawer as a side effect — unchanged pre-existing behaviour', () => {
    render(
      <App>
        <div>page content</div>
      </App>,
    );

    act(() => capturedOnMenuClick?.());
    expect(drawerMenuSpy).toHaveBeenLastCalledWith(expect.objectContaining({ isOpen: true }));

    act(() => capturedOnMyCartClick?.());
    expect(drawerMenuSpy).toHaveBeenLastCalledWith(expect.objectContaining({ isOpen: false }));
  });
});

