describe('SFCC-315 — Add to Bag opens the cart drawer, not the base AddToCartModal', () => {
  test('opens the cart drawer with the real clicked button as the AC10 focus-return trigger — the PDP add-to-bag trigger origin', async () => {
    const onCartDrawerOpen = vi.fn();
    mockUseCartDrawer.mockReturnValue({ isOpen: false, onOpen: onCartDrawerOpen, onClose: vi.fn() });
    mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn().mockResolvedValue([{ itemId: 'sku-s' }])}
        controlledVariationValues={{ size: 'S' }}
        validateOrderability={() => true}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    const button = screen.getByTestId('zimm-add-to-bag');
    await userEvent.click(button);

    // The real button itself — not a wrapper, not document.activeElement — is what AC10 must
    // return focus to. See addToBagTriggerRef's own comment in index.tsx for the mechanism
    // (wrapping Box ref + querySelector, since ZimmButton's onClick carries no event and
    // ZimmButton isn't forwardRef).
    await waitFor(() => {
      expect(onCartDrawerOpen).toHaveBeenCalledWith(button);
    });
  });

  test('does not open the cart drawer when addToCart resolves with no items added', async () => {
    const onCartDrawerOpen = vi.fn();
    mockUseCartDrawer.mockReturnValue({ isOpen: false, onOpen: onCartDrawerOpen, onClose: vi.fn() });
    mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn().mockResolvedValue(null)}
        controlledVariationValues={{ size: 'S' }}
        validateOrderability={() => true}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    await userEvent.click(screen.getByTestId('zimm-add-to-bag'));

    expect(onCartDrawerOpen).not.toHaveBeenCalled();
  });

  test('does not open the cart drawer, and shows an error toast, when addToCart rejects', async () => {
    const onCartDrawerOpen = vi.fn();
    const showToast = vi.fn();
    mockUseCartDrawer.mockReturnValue({ isOpen: false, onOpen: onCartDrawerOpen, onClose: vi.fn() });
    mockUseToast.mockReturnValueOnce(showToast);
    mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn().mockRejectedValue(new Error('network error'))}
        controlledVariationValues={{ size: 'S' }}
        validateOrderability={() => true}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    await userEvent.click(screen.getByTestId('zimm-add-to-bag'));

    await waitFor(() => {
      expect(showToast).toHaveBeenCalledWith(expect.objectContaining({ status: 'error' }));
    });
    expect(onCartDrawerOpen).not.toHaveBeenCalled();
  });
});

