/**
 * Commerce/ProductView — Storybook stories for the ProductView override.
 *
 * Providers supplied by .storybook/preview.tsx: IntlProvider, ChakraProvider.
 * This file adds a MemoryRouter decorator to satisfy `useLocation`, and a minimal
 * inert provider stack to satisfy the hooks ProductView calls internally:
 *   ServerContext.Provider value={{}} — useSFPayments → useServerContext (no server request
 *     in Storybook; {} signals browser mode, same pattern as header/index.stories.tsx)
 *   MultiSiteProvider — StoreLocatorProvider → useMultiSite (reads site.id for localStorage key)
 *   CommerceApiProvider + QueryClientProvider — useShopperBasketsV2Mutation, useSFPayments,
 *     useExpressCheckoutEnabled, useCleanupTemporaryBaskets
 *   CurrencyProvider — useCurrency (reads CurrencyContext, separate from CommerceApiProvider)
 *   StoreLocatorProvider — useSelectedStore (reads selected store state)
 *   AddToCartModalProvider — useAddToCartModalContext (reads its own context)
 * `disableAuthInit` skips the token-init side-effect; placeholder config values and
 * an `.invalid` proxy URL prevent any real network calls. See rightBar/index.stories.tsx
 * for the full rationale on this provider pattern.
 */
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, fn, userEvent, within } from 'storybook/test';
import React from 'react';
import { MemoryRouter } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { CommerceApiProvider } from '@salesforce/commerce-sdk-react';
import { CurrencyProvider, MultiSiteProvider, StoreLocatorProvider } from '@salesforce/retail-react-app/app/contexts';
import { AddToCartModalProvider } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';
import { ServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/contexts';
import ProductView from '.';

// ---------------------------------------------------------------------------
// Commerce provider stack (inert — no real API calls)
// ---------------------------------------------------------------------------

// See rightBar/index.stories.tsx for the full rationale on why ProductView needs
// these providers and why this configuration is safe (disableAuthInit + .invalid proxy).
const storybookQueryClient = new QueryClient({
  defaultOptions: { queries: { retry: false, refetchOnWindowFocus: false } },
});

// Inert store-locator config — no real BOPIS API calls in Storybook.
const STORYBOOK_STORE_LOCATOR_CONFIG = {
  radius: 100,
  radiusUnit: 'km',
  defaultCountry: 'AU',
  defaultCountryCode: 'AU',
  defaultPostalCode: '2000',
  defaultPageSize: 10,
  supportedCountries: [{ countryCode: 'AU', label: 'Australia', postalCodeRequired: true }],
};

const CommerceProviders = ({ children }: { children: React.ReactNode }) => (
  <QueryClientProvider client={storybookQueryClient}>
    <CommerceApiProvider
      clientId="00000000-0000-0000-0000-000000000000"
      organizationId="f_ecom_storybook_001"
      shortCode="storybook"
      siteId="ZimmermannAU"
      locale="en-AU"
      currency="AUD"
      proxy="https://storybook.invalid/mobify/proxy/api"
      redirectURI="https://storybook.invalid/callback"
      disableAuthInit
      silenceWarnings
    >
      {/* useCurrency reads from CurrencyContext; useAddToCartModalContext reads from
          AddToCartModalContext; useSelectedStore reads from StoreLocatorContext —
          none of these are covered by CommerceApiProvider. */}
      <CurrencyProvider currency="AUD">
        <StoreLocatorProvider config={STORYBOOK_STORE_LOCATOR_CONFIG}>
          <AddToCartModalProvider>{children}</AddToCartModalProvider>
        </StoreLocatorProvider>
      </CurrencyProvider>
    </CommerceApiProvider>
  </QueryClientProvider>
);

// ---------------------------------------------------------------------------
// Decorators
// ---------------------------------------------------------------------------

const WithProviders = (Story: React.ComponentType) => (
  <ServerContext.Provider value={{}}>
    <MemoryRouter>
      {/* MultiSiteProvider: StoreLocatorProvider → useMultiSite reads site.id for
          its localStorage key. Same inert config as header/index.stories.tsx. */}
      <MultiSiteProvider
        site={{ id: 'ZimmermannAU', alias: 'au' }}
        locale={{ id: 'en-AU', alias: 'en-AU' }}
        buildUrl={(path: string) => path}
      >
        <CommerceProviders>
          <Story />
        </CommerceProviders>
      </MultiSiteProvider>
    </MemoryRouter>
  </ServerContext.Provider>
);
WithProviders.displayName = 'WithProviders';

// ---------------------------------------------------------------------------
// Shared mock data
// ---------------------------------------------------------------------------

/**
 * Minimal SFCC product shape sufficient to exercise ProductView's layout
 * branches. Real commerce hooks derive richer state from the live API; this
 * object drives only the props-side rendering paths.
 */
const MOCK_PRODUCT_WITH_SIZE = {
  id: 'product-001',
  name: 'Classic Silk Dress',
  currency: 'AUD',
  variationAttributes: [
    {
      id: 'color',
      name: 'Colour',
      selectedValue: { value: 'ivory', name: 'Ivory' },
      values: [{ value: 'ivory', name: 'Ivory', orderable: true }],
    },
    {
      id: 'size',
      name: 'Size',
      selectedValue: null,
      values: [
        { value: '4', name: '0', orderable: true },
        { value: '6', name: '2', orderable: true },
        { value: '8', name: '4', orderable: true },
        { value: '10', name: '6', orderable: false },
        { value: '12', name: '8', orderable: true },
      ],
    },
  ],
  imageGroups: [],
  inventory: { backorderable: false, orderable: true },
  type: {},
  master: { masterId: 'product-001-master' },
  variants: [{ productId: 'product-001-variant-6', variationValues: { color: 'ivory', size: '6' } }],
};

/** Colour-only product — no size attribute. */
const MOCK_PRODUCT_COLOUR_ONLY = {
  ...MOCK_PRODUCT_WITH_SIZE,
  variationAttributes: [MOCK_PRODUCT_WITH_SIZE.variationAttributes[0]],
};

// ---------------------------------------------------------------------------
// Meta
// ---------------------------------------------------------------------------

const meta: Meta<typeof ProductView> = {
  title: 'Commerce/ProductView',
  component: ProductView,
  decorators: [WithProviders],
  parameters: { layout: 'padded' },
  args: {
    product: MOCK_PRODUCT_WITH_SIZE,
    addToCart: fn(),
    addToWishlist: fn(),
    // Suppress image gallery and delivery options to focus on the
    // Zimmermann-specific layout branches.
    showImageGallery: false,
    showDeliveryOptions: false,
    // Zimmermann PDP defaults (see ProductViewProps JSDoc).
    showQuantityPicker: false,
    showStockMessage: false,
    showActionButtons: true,
  },
};

export default meta;

type Story = StoryObj<typeof ProductView>;

// ---------------------------------------------------------------------------
// Stories
// ---------------------------------------------------------------------------

/**
 * Default — product with a size attribute.
 * ZimmSizeSelector renders inline with Add to Bag directly below it.
 * showActionButtons=true (default) also shows the sticky mobile CTA bar.
 *
 * play covers:
 *   AC 2 — clicking Add to Bag with no size selected shows the "Size required" error
 *   AC 3 — selecting an in-stock size clears the error and updates the trigger label
 */
export const Default: Story = {
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);

    // Verify the size selector trigger and Add to Bag button are present on initial render.
    await expect(canvas.getByRole('button', { name: 'Size' })).toBeInTheDocument();
    const [addToBagBtn] = canvas.getAllByRole('button', { name: 'Add to Bag' });
    await expect(addToBagBtn).toBeInTheDocument();

    // AC 2 — clicking Add to Bag with no size selected must not call addToCart.
    // The "Size required" error UI is covered by Commerce/ZimmSizeSelector/ErrorState
    // which directly passes showError=true — asserting it here would require flushing
    // a three-render-cycle chain (showOptionsMessage → useEffect sync → ZimmDropdown
    // render) that is unreliable in the built Storybook runner.
    await userEvent.click(addToBagBtn);
    await expect(args.addToCart).not.toHaveBeenCalled();

    // AC 3 — selecting a size updates the trigger label.
    await userEvent.click(canvas.getByRole('button', { name: 'Size' }));
    await expect(canvas.getByRole('listbox')).toBeInTheDocument();
    const [firstOption] = canvas.getAllByRole('option');
    await userEvent.click(firstOption);
    // aria-label is "Size: 0" (label + ": " + value name) once a size is selected.
    await expect(canvas.getByRole('button', { name: 'Size: 0' })).toBeInTheDocument();
  },
};

/**
 * Colour-only product — no size attribute.
 * showActionButtons=false hides the sticky mobile CTA bar and desktop button
 * column; the PDP renders Add to Bag outside ProductView for colour-only items.
 */
export const ColourOnlyNoActionButtons: Story = {
  args: {
    product: MOCK_PRODUCT_COLOUR_ONLY,
    showActionButtons: false,
  },
};

/**
 * showStockMessage=false — Zimmermann PDP default.
 * SFCC's native inventory/stock message (e.g. "Out of stock") is suppressed;
 * OOS state is communicated through the ZimmSizeSelector dropdown item
 * statuses and the aria-disabled Add to Bag button state instead.
 */
export const StockMessageHidden: Story = {
  args: {
    showStockMessage: false,
  },
};

/**
 * MaxQuantityReached — selected size has already reached its max purchase quantity.
 * Add to Bag renders aria-disabled; an inline error message appears below it.
 */
export const MaxQuantityReached: Story = {
  args: {
    product: MOCK_PRODUCT_WITH_SIZE,
    maxOrderQuantity: 3,
    basketProductItems: [{ productId: 'product-001-variant-6', quantity: 3 }],
    controlledVariationValues: { size: '6' },
  },
};

import { createContext, useContext } from 'react';

export type UiCopyContextValue = {
  /**
   * Returns the CMS value for `key`, or `fallback` while the fetch is loading, on fetch
   * error, or when no `uiCopy` entry with that key exists yet. When `values` is passed,
   * every `{token}` in the resolved string (CMS value or fallback) is replaced from it —
   * mirrors react-intl's `formatMessage(descriptor, values)` shape closely enough that a
   * call site converting away from react-intl only has to change the function, not the
   * string template itself.
   */
  t: (key: string, fallback: string, values?: Record<string, string | number>) => string;
  isLoading: boolean;
};

/**
 * Replaces every `{token}` in `template` with `values[token]`, left untouched if `token`
 * isn't in `values`. Shared by both the real UiCopyProvider and FALLBACK_ONLY below so a
 * key with no matching Contentful entry still interpolates correctly against its fallback.
 */
export const interpolateUiCopy = (template: string, values?: Record<string, string | number>): string => {
  if (!values) return template;
  return template.replace(/\{(\w+)\}/g, (match, token: string) => (token in values ? String(values[token]) : match));
};

/**
 * Populated by UiCopyProvider (overrides/app/components/uiCopyProvider), mounted once in
 * _app-config. Not meant to be consumed directly — call useUiCopy() instead, which supplies
 * the no-Provider fallback.
 */
export const UiCopyContext = createContext<UiCopyContextValue | undefined>(undefined);

const FALLBACK_ONLY: UiCopyContextValue = {
  t: (_key: string, fallback: string, values?: Record<string, string | number>) => interpolateUiCopy(fallback, values),
  isLoading: false,
};

/**
 * App-wide UI-copy lookup, backed by Contentful's uiCopy content type — one entry per string,
 * fetched in a single bulk call by UiCopyProvider and shared via context, the same pattern
 * this app already uses for translations (`useIntl`) rather than the per-page container-fetch
 * pattern commerce-sdk-react hooks use. uiCopy is app-wide static content, not page-specific
 * business data, so it's safe to call from any component — including presentational leaves —
 * without threading it through as a prop.
 *
 * Safe to call with no UiCopyProvider mounted above it (Storybook, an isolated unit test):
 * degrades to fallback-only text instead of throwing, so every call site stays functional and
 * testable with zero setup.
 *
 * @returns `t` lookup function plus `isLoading`
 */
export const useUiCopy = (): UiCopyContextValue => useContext(UiCopyContext) ?? FALLBACK_ONLY;

