/**
 * Reads the shared cart-drawer state from Context. For any consumer that is a genuine descendant
 * of `CartDrawerProvider` (e.g. `product-view`) — see this file's own module docblock for why
 * `_app` itself must use `useCartDrawerState()` directly instead. Throws outside a Provider
 * (matching `useIntl`'s own real, non-degrading behaviour for the same "this is load-bearing
 * business logic, not optional content" reasoning `components.md` documents for that hook) rather
 * than silently returning a no-op, since a missing Provider here means add-to-bag feedback is
 * broken, not just cosmetically absent.
 *
 * @returns The shared cart-drawer state — see `CartDrawerContextValue`.
 */
export const useCartDrawer = (): CartDrawerContextValue => {
  const ctx = useContext(CartDrawerContext);
  if (!ctx) {
    throw new Error('useCartDrawer must be used within a CartDrawerProvider');
  }
  return ctx;
};

