import { chromium } from 'playwright';

const storyId = process.argv[2] || 'commerce-productview--default';
const url = `http://localhost:6006/iframe.html?id=${storyId}&viewMode=story`;

const browser = await chromium.launch();
const page = await browser.newPage();
const consoleErrors = [];
page.on('pageerror', (err) => consoleErrors.push(`pageerror: ${err.message}`));
page.on('console', (msg) => {
  if (msg.type() === 'error') consoleErrors.push(`console.error: ${msg.text()}`);
});

await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 });
await page.waitForTimeout(1500);

const bodyText = await page.evaluate(() => document.body.innerText);
const hasAddToBag = await page
  .getByRole('button', { name: /add to bag/i })
  .first()
  .isVisible()
  .catch(() => false);

console.log('--- STORY:', storyId, '---');
console.log('Add to Bag button visible:', hasAddToBag);
console.log('Contains "must be used within":', bodyText.includes('must be used within'));
console.log('Contains "Something went wrong":', bodyText.includes('Something went wrong'));
console.log('Console/page errors:', JSON.stringify(consoleErrors, null, 2));
console.log('Body text (first 500 chars):', bodyText.slice(0, 500));

await browser.close();

