            if (cartItem.bonusProductLineItem && cartItem.bonusDiscountLineItemId) {
                const id = cartItem.bonusDiscountLineItemId
                map[id] = (map[id] || 0) + (cartItem.quantity || 0)
            }
        })
        return map
    }, [basket?.productItems])

    if (!isOpen) {
