// Regression coverage for the AddToCartModalProvider removal-then-restoration (SFCC-11 plan
// step 9). This mock builds a real Context/Provider/hook trio — not a bare passthrough — so
// AddToCartModalProbe below (standing in for the real, un-mockable-under-Vitest AddToCartModal,
// see that component's own comment) genuinely observes `undefined` if AddToCartModalProvider
// is ever removed from _app again, the same as the real base component would.
const AddToCartModalContext = React.createContext<{ isOpen: boolean; onClose: () => void; data: null } | undefined>(
  undefined,
);
vi.mock('@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal', () => ({
  AddToCartModalProvider: ({ children }: { children: React.ReactNode }) => (
    <AddToCartModalContext.Provider value={{ isOpen: false, onClose: vi.fn(), data: null }}>
      {children}
    </AddToCartModalContext.Provider>
  ),
  useAddToCartModalContext: () => React.useContext(AddToCartModalContext),
}));
import { useAddToCartModalContext } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';

// Stands in for the real base AddToCartModal (use-add-to-cart-modal.js:76-77), which
// BonusProductSelectionModalProvider renders unconditionally as its own child
// (bonus-product-modal-provider.js:33) on every page. A real, unmocked render of that base
// `.js`-with-JSX file isn't reachable under this project's Vitest config (a separate,
// pre-existing tooling gap — same class as the documented ZimmIcon-under-Vitest gap in
// testing.md) — this probe reproduces its one load-bearing line instead:
// `const {isOpen, onClose, data} = useAddToCartModalContext()`, with no guard. If
// AddToCartModalProvider is ever removed from _app again, useAddToCartModalContext() resolves
// to undefined here exactly as it would for the real component, and this destructure throws.
const addToCartModalProbeSpy = vi.fn();
const AddToCartModalProbe = () => {
  const ctx = useAddToCartModalContext();
  // Non-null assertion is deliberate, not a TS convenience: the real base component has no
  // guard either (it's a plain, unchecked destructure) — asserting it away here would test a
  // different, safer shape than what actually ships.
  const { isOpen } = ctx!;
  addToCartModalProbeSpy(isOpen);
  return null;
};
vi.mock('@salesforce/retail-react-app/app/hooks/use-bonus-product-selection-modal', () => ({
  BonusProductSelectionModalProvider: ({ children }: { children: React.ReactNode }) => (
    <>
      {children}
      <AddToCartModalProbe />
    </>
  ),
}));

