    addToCartModalProbeSpy.mockClear();
  });

  test('AddToCartModalProbe (standing in for the real, always-rendered base AddToCartModal) resolves a defined context instead of throwing', () => {
    // BonusProductSelectionModalProvider (mocked above to render this probe in AddToCartModal's
    // own slot) is mounted on every page, unconditionally, and always renders that slot — so if
    // AddToCartModalProvider is ever missing above it, this throws on every single page, not
    // just on an add-to-cart interaction. expect(...).not.toThrow() is the correct assertion
    // shape here: React re-throws a render-time error synchronously out of render() when no
    // error boundary sits between the throwing component and the root, which _app has none of
    // for this slot.
    expect(() =>
      render(
        <App>
          <div>page content</div>
        </App>,
      ),
    ).not.toThrow();

    expect(addToCartModalProbeSpy).toHaveBeenCalledWith(false);
  });
});

